insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('loan-documents','loan-documents',false,10485760,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;
create policy cgf_document_upload on storage.objects for insert to authenticated with check (bucket_id='loan-documents' and exists(select 1 from public.loan_applications l where l.id::text=(storage.foldername(name))[1] and l.bank_id=public.current_user_bank_id() and l.status in ('draft','docs_incomplete') and public.current_user_role_code() in ('bank_admin','bank_officer')));
create policy cgf_document_read on storage.objects for select to authenticated using (bucket_id='loan-documents' and exists(select 1 from public.loan_applications l where l.id::text=(storage.foldername(name))[1] and (l.bank_id=public.current_user_bank_id() or public.is_prsf_staff())));
create policy cgf_document_cleanup on storage.objects for delete to authenticated using (bucket_id='loan-documents' and exists(select 1 from public.loan_applications l where l.id::text=(storage.foldername(name))[1] and l.bank_id=public.current_user_bank_id() and l.status in ('draft','docs_incomplete')) and not exists(select 1 from public.loan_documents d where d.file_path=name));
create policy cgf_document_insert_scope on public.loan_documents as restrictive for insert to authenticated with check (uploaded_by=auth.uid() and exists(select 1 from public.loan_applications l where l.id=loan_id and l.bank_id=public.current_user_bank_id() and l.status in ('draft','docs_incomplete') and public.current_user_role_code() in ('bank_admin','bank_officer')) and exists(select 1 from storage.objects o where o.bucket_id='loan-documents' and o.name=file_path and (storage.foldername(o.name))[1]=loan_id::text));
create policy cgf_document_no_update on public.loan_documents as restrictive for update to authenticated using(false) with check(false);
create policy cgf_document_no_delete on public.loan_documents as restrictive for delete to authenticated using(false);
create policy cgf_sector_admin_insert on public.sectors as restrictive for insert to authenticated with check (public.current_user_role_code() in ('super_admin','prsf_admin'));
create policy cgf_sector_admin_delete on public.sectors as restrictive for delete to authenticated using (public.current_user_role_code() in ('super_admin','prsf_admin'));
